package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer.writeNumber(BigDecimal)
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // We use a real codec to ensure the TokenBuffer behaves correctly during serialization
        tokenBuffer = new TokenBuffer(mapper);
    }

    /**
     * Tests the branch where dec is null.
     * The method calls writeNull().
     */
    @Test
    public void testWriteNumber_WithNull() throws IOException {
        tokenBuffer.writeNumber((BigDecimal) null);

        // To verify writeNull() was called, we serialize to a string and check content
        String result = tokenBuffer.toString();
        Assert.assertEquals("null", result);
    }

    /**
     * Tests the branch where dec is not null.
     * The method executes the empty else block.
     */
    @Test
    public void testWriteNumber_WithValidBigDecimal() throws IOException {
        BigDecimal value = new BigDecimal("123.456");
        tokenBuffer.writeNumber(value);

        // Verify the value is correctly recorded in the buffer
        String result = tokenBuffer.toString();
        Assert.assertEquals("123.456", result);
    }

    /**
     * Tests the branch where dec is not null with a zero value.
     */
    @Test
    public void testWriteNumber_WithZero() throws IOException {
        BigDecimal value = BigDecimal.ZERO;
        tokenBuffer.writeNumber(value);

        String result = tokenBuffer.toString();
        Assert.assertEquals("0", result);
    }

    /**
     * Tests the branch where dec is not null with a very large value.
     */
    @Test
    public void testWriteNumber_WithLargeBigDecimal() throws IOException {
        BigDecimal value = new BigDecimal("123456789012345678901234567890");
        tokenBuffer.writeNumber(value);

        String result = tokenBuffer.toString();
        Assert.assertEquals("123456789012345678901234567890", result);
    }
}
